# Pulumi ComponentResource: Service Stack (TypeScript)

## 1. Component Definition

**`src/serviceStack.ts`** — The ComponentResource wrapper

```typescript
import * as pulumi from "@pulumi/pulumi";
import * as aws from "@pulumi/aws";
import * as iam from "@pulumi/aws/iam";

interface ServiceStackArgs {
  environment: "dev" | "prod";
  bucketName: string;
  dbInstanceClass: string;
  dbAllocatedStorage: number;
  enableMultiAz: boolean;
  dbBackupRetentionDays: number;
  kmsKeyArn?: string;
  vpcSecurityGroupIds: string[];
  dbSubnetGroupName: string;
  tags: Record<string, string>;
}

export class ServiceStack extends pulumi.ComponentResource {
  // Outputs
  public readonly bucketName: pulumi.Output<string>;
  public readonly bucketArn: pulumi.Output<string>;
  public readonly bucketVersioningId: pulumi.Output<string>;

  public readonly dbInstance: aws.rds.Instance;
  public readonly dbEndpoint: pulumi.Output<string>;
  public readonly dbPort: pulumi.Output<number>;

  public readonly serviceRole: aws.iam.Role;
  public readonly serviceRoleArn: pulumi.Output<string>;

  constructor(
    name: string,
    args: ServiceStackArgs,
    opts?: pulumi.ComponentResourceOptions
  ) {
    super("custom:service:ServiceStack", name, {}, opts);

    const baseOpts = { parent: this, dependsOn: opts?.dependsOn || [] };
    const config = new pulumi.Config();

    // ─────────────────────────────────────────────────────────────
    // 1. S3 BUCKET with versioning & encryption
    // ─────────────────────────────────────────────────────────────
    const bucket = new aws.s3.Bucket(
      `${name}-bucket`,
      {
        bucketPrefix: args.bucketName,
        forceDestroy: args.environment === "dev", // Only for dev cleanup
        tags: args.tags,
      },
      baseOpts
    );

    // Enable versioning
    const versioning = new aws.s3.BucketVersioningV2(
      `${name}-versioning`,
      {
        bucket: bucket.id,
        versioningConfiguration: {
          status: "Enabled",
        },
      },
      baseOpts
    );

    // Server-side encryption (AES-256 by default, KMS in prod)
    const serverSideEncryptionConfig: aws.s3.BucketServerSideEncryptionConfigurationV2Args =
      args.environment === "prod" && args.kmsKeyArn
        ? {
            bucket: bucket.id,
            rule: {
              applyServerSideEncryptionByDefault: {
                sseAlgorithm: "aws:kms",
                kmsMasterKeyId: args.kmsKeyArn,
              },
              bucketKeyEnabled: true,
            },
          }
        : {
            bucket: bucket.id,
            rule: {
              applyServerSideEncryptionByDefault: {
                sseAlgorithm: "AES256",
              },
            },
          };

    const encryption = new aws.s3.BucketServerSideEncryptionConfigurationV2(
      `${name}-encryption`,
      serverSideEncryptionConfig,
      baseOpts
    );

    // Block public access
    const publicAccessBlock = new aws.s3.BucketPublicAccessBlock(
      `${name}-public-block`,
      {
        bucket: bucket.id,
        blockPublicAcls: true,
        blockPublicPolicy: true,
        ignorePublicAcls: true,
        restrictPublicBuckets: true,
      },
      baseOpts
    );

    // Cross-region replication for prod
    if (args.environment === "prod") {
      const replicationRole = new aws.iam.Role(
        `${name}-replication-role`,
        {
          assumeRolePolicy: JSON.stringify({
            Version: "2012-10-17",
            Statement: [
              {
                Effect: "Allow",
                Principal: { Service: "s3.amazonaws.com" },
                Action: "sts:AssumeRole",
              },
            ],
          }),
          tags: args.tags,
        },
        baseOpts
      );

      new aws.iam.RolePolicy(
        `${name}-replication-policy`,
        {
          role: replicationRole.id,
          policy: pulumi.output([bucket.arn, bucket.arn]).apply((arns) =>
            JSON.stringify({
              Version: "2012-10-17",
              Statement: [
                {
                  Effect: "Allow",
                  Action: [
                    "s3:GetReplicationConfiguration",
                    "s3:ListBucket",
                  ],
                  Resource: arns[0],
                },
                {
                  Effect: "Allow",
                  Action: [
                    "s3:GetObjectVersionForReplication",
                    "s3:GetObjectVersionAcl",
                  ],
                  Resource: `${arns[0]}/*`,
                },
                {
                  Effect: "Allow",
                  Action: [
                    "s3:ReplicateObject",
                    "s3:ReplicateDelete",
                  ],
                  Resource: `arn:aws:s3:::${args.bucketName}-replica/*`,
                },
              ],
            })
          ),
        },
        baseOpts
      );

      new aws.s3.BucketReplicationConfiguration(
        `${name}-replication`,
        {
          role: replicationRole.arn,
          bucket: bucket.id,
          rules: [
            {
              id: "replicate-to-us-west-2",
              status: "Enabled",
              priority: 1,
              destination: {
                bucket: `arn:aws:s3:::${args.bucketName}-replica`,
                replicationTime: {
                  status: "Enabled",
                  time: 15,
                },
                metrics: {
                  status: "Enabled",
                  eventThreshold: 900,
                },
              },
              deleteMarkerReplication: {
                status: "Enabled",
              },
            },
          ],
        },
        { ...baseOpts, dependsOn: [versioning] }
      );
    }

    // ─────────────────────────────────────────────────────────────
    // 2. RDS POSTGRESQL INSTANCE
    // ─────────────────────────────────────────────────────────────
    const dbInstance = new aws.rds.Instance(
      `${name}-db`,
      {
        identifier: `${name}-postgres`,
        engine: "postgres",
        engineVersion: "15.3",
        instanceClass: args.dbInstanceClass,
        allocatedStorage: args.dbAllocatedStorage,
        storageType: "gp3",
        storageEncrypted: true,
        multiAz: args.enableMultiAz,
        dbSubnetGroupName: args.dbSubnetGroupName,
        vpcSecurityGroupIds: args.vpcSecurityGroupIds,
        dbName: "appdb",
        username: "postgres",
        password: config.requireSecret("dbPassword"), // From stack config secret
        port: 5432,
        publicly_accessible: false,
        backupRetentionPeriod: args.dbBackupRetentionDays,
        backupWindow: "03:00-04:00",
        maintenanceWindow: "mon:04:00-mon:05:00",
        skipFinalSnapshot: args.environment === "dev",
        finalSnapshotIdentifier:
          args.environment === "prod"
            ? `${name}-final-snapshot-${Date.now()}`
            : undefined,
        deleteProtection: args.environment === "prod",
        enableIamDatabaseAuthentication: true,
        enableCloudwatchLogsExports: ["postgresql"],
        tags: args.tags,
      },
      baseOpts
    );

    // ─────────────────────────────────────────────────────────────
    // 3. IAM ROLE FOR SERVICE ACCOUNTS
    // ─────────────────────────────────────────────────────────────
    const serviceRole = new aws.iam.Role(
      `${name}-service-role`,
      {
        assumeRolePolicy: JSON.stringify({
          Version: "2012-10-17",
          Statement: [
            args.environment === "prod"
              ? {
                  // OIDC trust for EKS service accounts (prod)
                  Effect: "Allow",
                  Principal: {
                    Federated: config.require("oidcProviderArn"), // From stack config
                  },
                  Action: "sts:AssumeRoleWithWebIdentity",
                  Condition: {
                    StringEquals: {
                      [`${config.require("oidcProviderUrl")}:sub`]:
                        "system:serviceaccount:default:app-sa",
                    },
                  },
                }
              : {
                  // Programmatic access (dev)
                  Effect: "Allow",
                  Principal: { AWS: `arn:aws:iam::${aws.getCallerIdentityOutput().accountId}:root` },
                  Action: "sts:AssumeRole",
                },
          ],
        }),
        tags: args.tags,
      },
      baseOpts
    );

    // Least-privilege S3 policy
    new aws.iam.RolePolicy(
      `${name}-s3-policy`,
      {
        role: serviceRole.id,
        policy: bucket.arn.apply((arn) =>
          JSON.stringify({
            Version: "2012-10-17",
            Statement: [
              {
                Effect: "Allow",
                Action: [
                  args.environment === "prod"
                    ? "s3:GetObject"
                    : "s3:GetObject",
                  args.environment === "prod" ? null : "s3:PutObject",
                ].filter(Boolean),
                Resource: `${arn}/*`,
              },
              {
                Effect: "Allow",
                Action: ["s3:ListBucket"],
                Resource: arn,
              },
            ],
          })
        ),
      },
      baseOpts
    );

    // RDS database access via IAM authentication
    new aws.iam.RolePolicy(
      `${name}-rds-policy`,
      {
        role: serviceRole.id,
        policy: dbInstance.arn.apply((arn) =>
          JSON.stringify({
            Version: "2012-10-17",
            Statement: [
              {
                Effect: "Allow",
                Action: ["rds-db:connect"],
                Resource: `${arn}:db:postgres`,
              },
            ],
          })
        ),
      },
      baseOpts
    );

    // ─────────────────────────────────────────────────────────────
    // Store outputs
    // ─────────────────────────────────────────────────────────────
    this.bucketName = bucket.id;
    this.bucketArn = bucket.arn;
    this.bucketVersioningId = versioning.id;

    this.dbInstance = dbInstance;
    this.dbEndpoint = dbInstance.endpoint.apply((e) =>
      e ? e.split(":")[0] : ""
    );
    this.dbPort = dbInstance.port;

    this.serviceRole = serviceRole;
    this.serviceRoleArn = serviceRole.arn;

    // Register outputs
    this.registerOutputs({
      bucketName: this.bucketName,
      bucketArn: this.bucketArn,
      dbEndpoint: this.dbEndpoint,
      dbPort: this.dbPort,
      serviceRoleArn: this.serviceRoleArn,
    });
  }
}
```

## 2. Stack Configuration Files

**`Pulumi.dev.yaml`**
```yaml
config:
  aws:region: us-east-1
  app:environment: dev
  app:dbInstanceClass: db.t3.micro
  app:dbAllocatedStorage: 20
  app:dbBackupRetentionDays: 7
  app:enableMultiAz: false
  app:dbPassword:
    secure: AAADACdJ3wqX7qZp9c+KiVc... # encrypted via `pulumi config set --secret`
  app:bucketName: my-app-assets-dev
```

**`Pulumi.prod.yaml`**
```yaml
config:
  aws:region: us-east-1
  app:environment: prod
  app:dbInstanceClass: db.t3.medium
  app:dbAllocatedStorage: 100
  app:dbBackupRetentionDays: 30
  app:enableMultiAz: true
  app:dbPassword:
    secure: AAADACdJ3wqX8rZp0d+LjWd... # different encrypted secret
  app:bucketName: my-app-assets-prod
  app:kmsKeyArn: arn:aws:kms:us-east-1:123456789012:key/12345678-1234-1234-1234-123456789012
  app:oidcProviderArn: arn:aws:iam::123456789012:oidc-provider/oidc.eks.us-east-1.amazonaws.com/id/EXAMPLED539D4633E53DE1B716D3041E
  app:oidcProviderUrl: oidc.eks.us-east-1.amazonaws.com/id/EXAMPLED539D4633E53DE1B716D3041E
```

## 3. Main Stack File

**`src/index.ts`**
```typescript
import * as pulumi from "@pulumi/pulumi";
import * as aws from "@pulumi/aws";
import { ServiceStack } from "./serviceStack";

const config = new pulumi.Config();
const stackName = pulumi.getStack();
const awsConfig = new pulumi.Config("aws");
const region = awsConfig.require("region");

// Fetch environment-specific config
const environment = config.require("environment") as "dev" | "prod";
const dbInstanceClass = config.require("dbInstanceClass");
const dbAllocatedStorage = config.requireNumber("dbAllocatedStorage");
const dbBackupRetentionDays = config.requireNumber("dbBackupRetentionDays");
const enableMultiAz = config.requireBoolean("enableMultiAz");
const bucketName = config.require("bucketName");
const kmsKeyArn = config.get("kmsKeyArn");

// Retrieve or create VPC resources (simplified)
const defaultVpc = aws.ec2.getVpc({
  default: true,
});

const dbSubnetGroup = new aws.rds.SubnetGroup(
  `${stackName}-db-subnet-group`,
  {
    subnetIds: (await defaultVpc).subnets.map((s) => s.id),
  }
);

const sgName = `${stackName}-db-sg`;
const securityGroup = new aws.ec2.SecurityGroup(sgName, {
  vpcId: (await defaultVpc).id,
  ingress: [
    {
      protocol: "tcp",
      fromPort: 5432,
      toPort: 5432,
      cidrBlocks: ["10.0.0.0/8"], // Restrict to VPC CIDR
    },
  ],
});

// Instantiate the ComponentResource
const serviceStack = new ServiceStack(
  `${stackName}-service`,
  {
    environment,
    bucketName,
    dbInstanceClass,
    dbAllocatedStorage,
    enableMultiAz,
    dbBackupRetentionDays,
    kmsKeyArn,
    vpcSecurityGroupIds: [securityGroup.id],
    dbSubnetGroupName: dbSubnetGroup.name,
    tags: {
      Environment: environment,
      Stack: stackName,
      ManagedBy: "Pulumi",
    },
  },
  { dependsOn: [securityGroup, dbSubnetGroup] }
);

// Export outputs
export const bucketName = serviceStack.bucketName;
export const bucketArn = serviceStack.bucketArn;
export const dbEndpoint = serviceStack.dbEndpoint;
export const dbPort = serviceStack.dbPort;
export const serviceRoleArn = serviceStack.serviceRoleArn;
```

## 4. Deployment Commands

```bash
# Set secrets (never in code)
pulumi config set --secret dbPassword "your-secure-password-dev" --stack dev
pulumi config set --secret dbPassword "your-secure-password-prod" --stack prod

# Deploy to dev
pulumi select dev
pulumi up

# Deploy to prod (no impact on dev)
pulumi select prod
pulumi up
```

## Key Features

✅ **S3 Bucket**: Versioning enabled, AES-256 encryption (KMS in prod), public access blocked  
✅ **RDS**: Deletion protection (prod), 7+ day backups, no public access, encrypted storage  
✅ **IAM**: Least-privilege S3/RDS policies, OIDC trust for EKS (prod), programmatic access (dev)  
✅ **Dev/Prod Separation**: Independent stack configs; prod has replication, multi-AZ, larger instance  
✅ **Secrets**: Database password via `pulumi config set --secret`; never in Git  
✅ **Idempotent**: ComponentResource encapsulation; changing prod does not affect dev state
